referenceSolutions.javascript:
export function encodeAndDecodeStrings(operation        , payload                 )                  {
if(operation==='encode')return (payload            ).map(s=>s.length+':'+s).join('');const s=payload          ,out         =[];let i=0;while(i<s.length){const colon=s.indexOf(':',i),n=Number(s.slice(i,colon));out.push(s.slice(colon+1,colon+1+n));i=colon+1+n;}return out;
}

